	private static function clusters_content() { $pillars = get_posts( array( 'post_type' => array( 'post', 'page' ), 'posts_per_page' => -1, 'meta_key' => self::key( 'pillar' ), 'meta_value' => 'on' ) ); echo '<p>Relaciona contenido pilar con sus páginas secundarias.</p><ul>'; foreach ( $pillars as $pillar ) { echo '<li><strong>' . esc_html( $pillar->post_title ) . '</strong>'; $children = get_posts( array( 'post_type' => array( 'post', 'page' ), 'posts_per_page' => -1, 'meta_key' => '_related_pillar', 'meta_value' => $pillar->ID ) ); if ( $children ) { echo '<ul>'; foreach ( $children as $child ) echo '<li>' . esc_html( $child->post_title ) . '</li>'; echo '</ul>'; } echo '</li>'; } if ( ! $pillars ) echo '<li>Aún no hay contenido pilar configurado.</li>'; echo '</ul>'; }
	public static function intents_page() { self::content_page( 'intents' ); }
	private static function intents_content() { $posts = get_posts( array( 'post_type' => 'post', 'posts_per_page' => -1 ) ); echo '<p>La actualización usa el proveedor configurado en AI y Chatbot para clasificar la keyword principal.</p><form method="post" action="' . esc_url( admin_url( 'admin-post.php' ) ) . '"><input type="hidden" name="action" value="digitalisimo_refresh_intents">'; wp_nonce_field( 'digitalisimo_refresh_intents' ); submit_button( 'Actualizar intenciones con OpenAI', 'secondary', 'submit', false ); echo '</form><table class="widefat striped"><thead><tr><th>Entrada</th><th>Keyword</th><th>Intención</th></tr></thead><tbody>'; foreach ( $posts as $post ) { $keyword = trim( explode( ',', (string) self::meta( $post->ID, 'keywords' ) )[0] ?? '' ); if ( $keyword ) echo '<tr><td>' . esc_html( $post->post_title ) . '</td><td>' . esc_html( $keyword ) . '</td><td>' . esc_html( get_post_meta( $post->ID, self::key( 'search_intent' ), true ) ) . '</td></tr>'; } echo '</tbody></table>'; }
